if(view==="clients"){
  if(!isPlatformAdmin){
    body=`<section class="pagehead"><span class="eyebrow">PLATFORMBEHEER</span><h1>Geen toegang</h1><p class="muted">Deze pagina is uitsluitend beschikbaar voor platformbeheer.</p></section>`;
  }else{
    const totalLeads=platformClients.reduce((n,c)=>n+Number(c.leads_count||0),0);
    const activeWidgets=platformClients.filter(c=>c.widget_enabled).length;
    const activePlans=platformClients.filter(c=>c.is_internal||["active","trialing"].includes(c.subscription_status)||c.plan==="trial").length;
    const widgetOrigin="https://reception-ai-luxwash.vercel.app";
    body=`<section class="pagehead"><span class="eyebrow">PLATFORMBEHEER</span><h1>Klanten & Widgets</h1><p class="muted">Beheer alle Reception AI-klanten vanuit één overzicht. Wijzigingen lopen via een beveiligde platformbeheerfunctie; tenant-RLS blijft intact.</p></section>
    ${platformLoadError?`<div class="notice error">${esc(platformLoadError)}</div>`:""}
    <section class="grid clientsummary">
      <div class="card"><div class="muted">Klanten</div><div class="metric">${platformClients.length}</div></div>
      <div class="card"><div class="muted">Widgets actief</div><div class="metric">${activeWidgets}</div></div>
      <div class="card"><div class="muted">Leads totaal</div><div class="metric">${totalLeads}</div></div>
      <div class="card"><div class="muted">Actieve/trial accounts</div><div class="metric">${activePlans}</div></div>
    </section>
    <section class="card clienttoolbar"><div><h2>Alle bedrijven</h2><p class="muted">Zoek op bedrijfsnaam, plan of receptionist.</p></div><input id="clientSearch" type="search" placeholder="Zoek klant…"></section>
    <section id="clientGrid" class="clientgrid">${platformClients.map(c=>{
      const id=esc(c.organization_id),name=esc(c.business_name||c.organization_name||"Naamloos bedrijf"),token=String(c.widget_token||""),enabled=Boolean(c.widget_enabled);
      const embed=token?`<script src="${widgetOrigin}/widget.js" data-widget-token="${token}" defer><\/script>`:"";
      const testUrl=token?`${widgetOrigin}/?widget=${encodeURIComponent(token)}`:"#";
      const trial=c.trial_ends_at?new Date(c.trial_ends_at).toLocaleDateString("nl-BE",{day:"2-digit",month:"2-digit",year:"numeric"}):"—";
      return `<article class="card clientcard" data-search="${esc([c.business_name,c.organization_name,c.receptionist_name,c.plan,c.subscription_status].filter(Boolean).join(" ").toLowerCase())}">
        <div class="clienthead"><div><span class="eyebrow">${c.is_internal?"INTERN · €0":esc(c.plan||"trial")}</span><h2>${name}</h2><p class="muted">${esc(c.receptionist_name||"AI Assistent")} · abonnement ${esc(c.subscription_status||"—")}</p></div><span class="badge">${enabled?"WIDGET ACTIEF":"WIDGET UIT"}</span></div>
        <div class="clientstats"><span><b>${esc(c.leads_count||0)}</b> leads</span><span><b>${esc(c.conversations_count||0)}</b> gesprekken</span><span><b>${esc(c.appointments_active||0)}</b> afspraken</span><span>trial tot <b>${esc(trial)}</b></span></div>
        <div class="clientactions">
          <button class="clienteditbtn ghostbtn small" data-id="${id}" type="button">Bewerken</button>
          <button class="clientcopy ghostbtn small" data-code="${esc(embed)}" type="button" ${token?"":"disabled"}>Widgetcode</button>
          ${token?`<a class="ghostbtn small" target="_blank" rel="noopener" href="${esc(testUrl)}">Testen</a>`:`<button class="ghostbtn small" disabled>Testen</button>`}
          <button class="clienttoggle small" data-org="${id}" data-enabled="${enabled?"1":"0"}" type="button">${enabled?"Uitzetten":"Activeren"}</button>
          <button class="clientleads ghostbtn small" data-org="${id}" type="button">Leads</button>
        </div>
        <div id="edit-${id}" class="clientpanel" hidden>
          <form class="clientform" data-org="${id}">
            <div class="clientformgrid">
              <label>Bedrijfsnaam<input name="business_name" maxlength="120" value="${name}" required></label>
              <label>Receptionistnaam<input name="receptionist_name" maxlength="50" value="${esc(c.receptionist_name||"AI Assistent")}"></label>
              <label>Accentkleur<input name="widget_accent" maxlength="7" pattern="#[0-9A-Fa-f]{6}" value="${esc(c.widget_accent||"#6d5dfc")}"></label>
              <label>Notificatie-e-mail<input name="notification_email" type="email" value="${esc(c.notification_email||"")}"></label>
            </div>
            <label>Welkomstbericht<input name="widget_greeting" maxlength="180" value="${esc(c.widget_greeting||"Hallo! Waarmee kan ik helpen?")}"></label>
            <label>Toegestane widget-domeinen — één per regel<textarea name="widget_allowed_domains" placeholder="voorbeeld.be\nwww.voorbeeld.be">${esc(arr(c.widget_allowed_domains).join("\n"))}</textarea></label>
            <p class="muted">Leeg = widget mag op elk domein laden. Vul domeinen in om gekopieerde widgetcodes op andere websites te blokkeren.</p>
            <div class="clientchecks">
              <label class="check"><input name="widget_enabled" type="checkbox" ${enabled?"checked":""}> Widget actief</label>
              <label class="check"><input name="automation_enabled" type="checkbox" ${c.automation_enabled?"checked":""}> Automatisering actief</label>
            </div>
            <div class="clientactions"><button type="submit">Opslaan</button><span class="muted clientmsg"></span></div>
          </form>
        </div>
        <div id="leads-${id}" class="clientpanel" hidden><div class="muted clientleadstatus">Klik op Leads om recente aanvragen te laden.</div><div class="clientleadlist"></div></div>
      </article>`}).join("")||'<div class="card"><p class="muted">Nog geen klanten gevonden.</p></div>'}</section>`;
  }
}
if(view==="overview")body=`${internalAccount?`<div class="successbanner"><b>Platform Owner · intern account.</b> Alle SaaS-functies zijn permanent actief zonder abonnement.</div>`:""}<section class="pagehead"><span class="eyebrow">DASHBOARD</span><h1>Goed overzicht. Snelle opvolging.</h1><p class="muted">Bekijk wat uw AI-receptionist heeft opgevangen en wat menselijke aandacht nodig heeft.</p></section>${!configured?'<div class="notice"><b>Onboarding nog niet klaar.</b> Vul bedrijfsinformatie, diensten en kwalificatievragen in. <a href="?view=settings">Nu configureren →</a></div>':""}${readinessHtml}${metrics}<section class="card"><div class="sectionhead"><div><h2>Integraties</h2><p class="muted">Elke tenant gebruikt uitsluitend zijn eigen providerverbindingen. Niet-geconfigureerde kanalen blijven veilig geblokkeerd.</p></div></div><div class="grid">${["email","whatsapp","calendar","payment"].map(ch=>{const i=integrations.find(x=>x.channel===ch);const label={email:"E-mail",whatsapp:"WhatsApp",calendar:"Agenda",payment:"Betaling"}[ch];const state=i?.status||"needs_setup";return `<div class="step"><b>${esc(label)}</b><span class="badge">${esc(state)}</span><p class="muted">${esc(i?.provider||"Niet ingesteld")}</p>${i?.last_error?`<p class="error">${esc(i.last_error)}</p>`:""}</div>`}).join("")}</div></section><section class="twocol"><div class="card"><h2>Recente leads</h2><div class="flow">${(leads.data||[]).slice(0,6).map(x=>`<div class="step"><b>${esc(x.name||x.email||"Websitebezoeker")}</b><span class="score">score ${esc(x.score||0)}</span><p class="muted">${esc(x.summary||x.status)}</p></div>`).join("")||'<p class="muted">Nog geen leads.</p>'}</div><a class="textlink" href="?view=leads">Alle leads bekijken →</a></div><div class="card"><h2>Open opvolging</h2><div class="flow">${(tasks.data||[]).filter(x=>x.status==="open").map(x=>`<div class="step taskrow"><div><b>${esc(x.title)}</b><br><span class="muted">${esc(x.priority)}</span></div><button class="donebtn" data-id="${esc(x.id)}">Afhandelen</button></div>`).join("")||'<p class="muted">Alles bijgewerkt.</p>'}</div></div></section>`;
if(view==="operations")body=`<section class="pagehead"><span class="eyebrow">UITVOERING</span><h1>Operations</h1><p class="muted">Leg exacte afspraken vast, bevestig uitvoering en maak betaalverzoeken aan. Een verstreken afspraak wordt nooit vanzelf als uitgevoerd beschouwd.</p></section><section class="card"><h2>Afspraken</h2><div class="flow">${appointments.map(a=>{const lead=leadById(a.lead_id)||{};const payment=payments.find(p=>p.appointment_id===a.id&&p.status!=="paid")||payments.find(p=>p.appointment_id===a.id);return `<div class="step operationrow"><div><b>${esc(lead.name||lead.email||"Lead")}</b> <span class="badge">${esc(a.status)}</span><p class="muted">${esc(a.requested_text||"Geen aanvraagtekst")}</p>${a.provider_booking_id?`<p class="muted">Agenda: ${esc(a.provider||"provider")} · ${esc(a.provider_booking_id)}</p>`:""}<form class="apptform" data-id="${esc(a.id)}"><div class="chatmeta"><label>Start<input name="start" type="datetime-local" value="${esc(dtLocal(a.start_at))}"></label><label>Einde<input name="end" type="datetime-local" value="${esc(dtLocal(a.end_at))}"></label></div><label>Locatie<input name="location" value="${esc(a.location||"")}"></label><label>Status<select name="status"><option value="proposed" ${a.status==="proposed"?"selected":""}>Voorgesteld</option><option value="confirmed" ${a.status==="confirmed"?"selected":""}>Bevestigd</option></select></label><button>Planning opslaan</button></form><div class="opbuttons">${a.start_at&&a.end_at&&!["confirmed","completed","cancelled"].includes(a.status)?`<button class="confirmappt" data-id="${esc(a.id)}">Bevestig afspraak</button>`:""}${a.status==="confirmed"?(payment&&payment.status!=="paid"?`<button type="button" class="ghostbtn" disabled>Wacht op betaling</button>`:`<button class="completeappt" data-id="${esc(a.id)}">Markeer uitgevoerd</button>`):""}${a.status!=="completed"&&a.status!=="cancelled"?`<button class="cancelappt ghostbtn" data-id="${esc(a.id)}">Annuleer</button>`:""}</div>${["confirmed","completed"].includes(a.status)?`<form class="paymentform" data-appt="${esc(a.id)}" data-lead="${esc(a.lead_id)}"><label>Betaalbedrag (€)<input name="amount" type="number" min="0.01" step="0.01" value="${payment?.amount_cents?esc((payment.amount_cents/100).toFixed(2)):""}"></label><button>Betaalverzoek ${payment?"bijwerken":"aanmaken"}</button><span class="muted">${payment?`${esc(payment.status)} · ${esc(money(payment.amount_cents,payment.currency))}`:""}</span></form>`:a.status!=="cancelled"?'<p class="muted">Bevestig eerst de afspraak om een betaalverzoek aan te maken.</p>':""}</div><div class="opmsg muted" id="op-${esc(a.id)}"></div></div>`}).join("")||'<p class="muted">Nog geen afspraken.</p>'}</div></section><section class="card"><h2>Betalingen</h2><div class="flow">${payments.map(p=>{const lead=leadById(p.lead_id)||{};return `<div class="step"><b>${esc(lead.name||lead.email||"Lead")}</b> <span class="badge">${esc(p.status)}</span><p>${esc(money(p.amount_cents,p.currency))}</p><p class="muted">${esc(p.provider||"nog geen provider")}${p.provider_payment_id?" · "+esc(p.provider_payment_id):""}</p>${p.payment_url?`<a class="textlink" target="_blank" rel="noopener" href="${esc(p.payment_url)}">Open betaalpagina →</a>`:""}</div>`}).join("")||'<p class="muted">Nog geen betalingen.</p>'}</div></section><section class="card"><h2>Workflowproblemen</h2><p class="muted">Alleen geblokkeerde of definitief mislukte acties verschijnen hier. Provider- of OAuth-problemen hervatten meestal automatisch zodra de integratie hersteld is.</p><div class="flow">${workflowIssues.map(w=>{const lead=leadById(w.lead_id)||{};const unknown=String(w.last_error||"").toLowerCase().includes("delivery status is unknown");return `<div class="step"><div><b>${esc(w.action_type)}</b> <span class="badge">${esc(w.status)}</span><p class="muted">${esc(lead.name||lead.email||w.channel)} · ${esc(w.provider||w.channel)} · poging ${esc(w.attempts||0)}/${esc(w.max_attempts||5)}</p><p class="${unknown?"error":"muted"}">${esc(w.last_error||"Geen foutdetail")}</p></div><button class="retryworkflow" data-id="${esc(w.id)}" data-unknown="${unknown?"1":"0"}">Opnieuw proberen</button><div class="opmsg muted" id="wf-${esc(w.id)}"></div></div>`}).join("")||'<p class="muted">Geen geblokkeerde of mislukte workflowacties.</p>'}</div></section>`;
if(view==="activity")body=`<section class="pagehead"><span class="eyebrow">AUDITTRAIL</span><h1>Activiteit</h1><p class="muted">Recente gevoelige wijzigingen en workflowacties binnen deze organisatie. Credentials en tokens worden nooit in deze log opgeslagen.</p></section><section class="card"><div class="flow">${auditEvents.map(a=>{const when=new Date(a.created_at).toLocaleString("nl-BE",{dateStyle:"short",timeStyle:"short"});return `<div class="step"><div><b>${esc(a.event_type)}</b> <span class="badge">${esc(a.entity_type||"event")}</span><p class="muted">${esc(when)}${a.actor_user_id?" · gebruiker "+esc(String(a.actor_user_id).slice(0,8)):" · systeem"}</p><p class="muted">${esc(JSON.stringify(a.payload||{}))}</p></div></div>`}).join("")||'<p class="muted">Nog geen audit-events.</p>'}</div></section>`;
if(view==="jarvis")body=`<section class="pagehead"><span class="eyebrow">AI ORCHESTRATOR</span><h1>JARVIS</h1><p class="muted">Analyseert uw CRM, taken en handoffs en bepaalt welke agent nu de hoogste prioriteit heeft.</p>${can("business")?`<button id="jarvisRun" type="button">Analyseer mijn bedrijf</button>`:lock("business")}</section><section class="card"><div id="jarvisResult"><p class="muted">Nog geen analyse uitgevoerd.</p></div></section>`;
if(view==="leads")body=`<section class="pagehead"><span class="eyebrow">CRM</span><h1>Leads</h1><p class="muted">Kwalificeer en verplaats aanvragen door uw pipeline.</p></section><div class="card"><div class="flow leadlist">${(leads.data||[]).map(x=>`<div class="step leadrow"><div><b>${esc(x.name||x.email||"Websitebezoeker")}</b><div class="muted">${esc(x.email||x.phone||x.source)} · score ${esc(x.score||0)}</div><p>${esc(x.summary||"Geen samenvatting")}</p><div class="leadnext">AI-advies: <b>${esc(nextAction(x))}</b></div>${x.status==="won"?`${can("pro")?`<button class="reviewbtn" data-id="${esc(x.id)}">Review Agent</button>`:lock("pro")}<div class="reviewresult" id="review-${esc(x.id)}"></div>`:""}${!["won","lost"].includes(x.status)?`${can("pro")?`<button class="followbtn" data-id="${esc(x.id)}">Maak opvolging</button><div class="leadnext" id="follow-${esc(x.id)}"></div>`:lock("pro")}${can("business")?`<button class="salesbtn" data-id="${esc(x.id)}">Sales Analyse</button><button class="salestaskbtn ghostbtn" data-id="${esc(x.id)}">Maak Sales-taak</button>`:lock("business")}<div class="salesresult" id="sales-${esc(x.id)}"></div>`:""}</div><select class="leadstatus" data-id="${esc(x.id)}"><option value="new" ${x.status==="new"?"selected":""}>Nieuw</option><option value="qualifying" ${x.status==="qualifying"?"selected":""}>Kwalificeren</option><option value="qualified" ${x.status==="qualified"?"selected":""}>Gekwalificeerd</option><option value="follow_up" ${x.status==="follow_up"?"selected":""}>Opvolgen</option><option value="handoff" ${x.status==="handoff"?"selected":""}>Handoff</option><option value="won" ${x.status==="won"?"selected":""}>Gewonnen</option><option value="lost" ${x.status==="lost"?"selected":""}>Verloren</option></select></div>`).join("")||'<p class="muted">Nog geen leads.</p>'}</div></div>`;
if(view==="agents"){const salesCfg=agentData.sales||{},marketingCfg=agentData.marketing||{},campaigns=agentData.campaigns||[],salesQueue=agentData.sales_queue||[];body=`<section class="pagehead"><span class="eyebrow">AI WORKFORCE</span><h1>Sales & Marketing Agents</h1><p class="muted">Configureer commerciële agents die werken op echte CRM-signalen. Ze maken analyses, taken en campagnedrafts; externe acties gebeuren niet zonder uw expliciete workflow of kanaalconfiguratie.</p></section>${agentLoadError?`<div class="notice">${esc(agentLoadError)}</div>`:""}<section class="agentgrid"><article class="card agent live"><span class="agentstatus">ACTIEF</span><h2>🎧 Receptionist</h2><p class="muted">Beantwoordt klantvragen, detecteert intentie en registreert leads.</p><a class="textlink" href="?view=receptionist">Open Receptionist →</a></article><article class="card agent live"><span class="agentstatus">ACTIEF</span><h2>🎯 Lead Agent</h2><p class="muted">Kwalificeert prospects en maakt opvolgtaken.</p><a class="textlink" href="?view=leads">Open Leads →</a></article><article class="card agent live"><span class="agentstatus">${salesCfg.active?"ACTIEF":"CONFIGUREER"}</span><h2>💼 Sales Agent</h2><p class="muted">Analyseert leadtemperatuur, verkoopfase, volgende actie, ontbrekende informatie en het beste kanaal. Kan met één klik een Sales-opvolgtaak maken.</p><a class="textlink" href="?view=leads">Analyseer leads →</a></article><article class="card agent live"><span class="agentstatus">${marketingCfg.active?"ACTIEF":"CONFIGUREER"}</span><h2>📣 Marketing Agent</h2><p class="muted">Maakt kanaalspecifieke campagnedrafts vanuit uw bedrijfsprofiel en CRM-signalen.</p></article></section>
<section class="twocol agentconfigs">
  <div class="card formcard">
    <div class="sectionhead"><div><h2>💼 Sales Agent instellen</h2><p class="muted">Bepaal vanaf welke score de agent een verkoopkans als opvolgbaar behandelt.</p></div><span class="badge">${salesCfg.active?"ACTIVE":"OFF"}</span></div>
    <form id="salesAgentConfig">
      <label>Naam agent</label><input id="salesName" maxlength="120" value="${esc(salesCfg.name||"Sales Agent")}">
      <label>Salesdoel</label><textarea id="salesObjective" placeholder="Bijv. warme leads omzetten naar een concrete afspraak">${esc(salesCfg.objective||"")}</textarea>
      <label>Aanbod / commerciële context</label><textarea id="salesOffer" placeholder="Wat mag de agent gebruiken om de volgende stap voor te stellen?">${esc(salesCfg.offer||"")}</textarea>
      <div class="clientformgrid">
        <label>Minimumscore<input id="salesMinScore" type="number" min="0" max="100" value="${esc(salesCfg.min_score??60)}"></label>
        <label>Opvolging binnen (uur)<input id="salesDueHours" type="number" min="1" max="720" value="${esc(salesCfg.follow_up_due_hours??24)}"></label>
      </div>
      <label>Voorkeurskanaal</label><select id="salesChannel">${["auto","email","whatsapp","phone","crm"].map(x=>`<option value="${x}" ${String(salesCfg.preferred_channel||"auto")===x?"selected":""}>${({auto:"Automatisch",email:"E-mail",whatsapp:"WhatsApp",phone:"Telefoon",crm:"CRM"})[x]}</option>`).join("")}</select>
      <label>Tone of voice</label><input id="salesTone" maxlength="500" value="${esc(salesCfg.tone||"menselijk, professioneel en compact")}">
      <label>Extra instructies</label><textarea id="salesInstructions">${esc(salesCfg.instructions||"")}</textarea>
      <label class="check"><input id="salesActive" type="checkbox" ${salesCfg.active?"checked":""}> Sales Agent actief</label>
      <label class="check"><input id="salesTaskDefault" type="checkbox" ${salesCfg.create_task_by_default!==false?"checked":""}> Standaard een menselijke opvolgtaak voorstellen</label>
      <button type="submit">Sales Agent opslaan</button>
    </form><div id="salesConfigMsg" class="result muted"></div>
  </div>
  <div class="card formcard">
    <div class="sectionhead"><div><h2>📣 Marketing Agent instellen</h2><p class="muted">Laat campagnes aansluiten op echte klantvragen in plaats van generieke content.</p></div><span class="badge">${marketingCfg.active?"ACTIVE":"OFF"}</span></div>
    <form id="marketingAgentConfig">
      <label>Naam agent</label><input id="marketingName" maxlength="120" value="${esc(marketingCfg.name||"Marketing Agent")}">
      <label>Doelgroep</label><textarea id="marketingAudience">${esc(marketingCfg.target_audience||"")}</textarea>
      <label>Positionering</label><textarea id="marketingPositioning">${esc(marketingCfg.positioning||"")}</textarea>
      <label>Kanalen — één per regel</label><textarea id="marketingChannels">${esc(arr(marketingCfg.channels).join("\n"))}</textarea>
      <label>Contentpijlers — één per regel</label><textarea id="marketingPillars">${esc(arr(marketingCfg.content_pillars).join("\n"))}</textarea>
      <div class="clientformgrid">
        <label>Posts per week<input id="marketingCadence" type="number" min="1" max="21" value="${esc(marketingCfg.cadence_per_week??3)}"></label>
        <label>Tone of voice<input id="marketingTone" maxlength="500" value="${esc(marketingCfg.tone||"menselijk, lokaal en betrouwbaar")}"></label>
      </div>
      <label>Call-to-action</label><input id="marketingCta" maxlength="500" value="${esc(marketingCfg.call_to_action||"Neem contact op voor meer informatie")}">
      <label>Extra instructies</label><textarea id="marketingInstructions">${esc(marketingCfg.instructions||"")}</textarea>
      <label class="check"><input id="marketingActive" type="checkbox" ${marketingCfg.active?"checked":""}> Marketing Agent actief</label>
      <label class="check"><input id="marketingSaveDrafts" type="checkbox" ${marketingCfg.save_drafts!==false?"checked":""}> Gegenereerde campagnes als draft bewaren</label>
      <button type="submit">Marketing Agent opslaan</button>
    </form><div id="marketingConfigMsg" class="result muted"></div>
  </div>
</section>
<section class="card">
  <div class="sectionhead"><div><h2>🔥 Sales-prioriteiten</h2><p class="muted">Hoogste CRM-kansen eerst. Contactgegevens en eerdere Sales-analyse worden meegenomen.</p></div><div class="clientactions"><button class="salesbatchbtn ghostbtn small" type="button">Analyseer alle warme leads</button><a class="textlink" href="?view=leads">Alle leads →</a></div></div><div id="salesBatchMsg" class="result muted"></div>
  <div class="flow">${salesQueue.length?salesQueue.slice(0,8).map(x=>{const o=x.opportunity||{};return `<div class="step salesqueueitem"><div><b>${esc(x.name||x.email||x.phone||"Websitebezoeker")}</b> <span class="badge">score ${esc(x.score||0)}</span><p>${esc(x.summary||"Geen samenvatting")}</p><p class="muted">${x.has_contact?"Contact beschikbaar":"Geen e-mail/telefoon"}${o.temperature?" · "+esc(String(o.temperature).toUpperCase())+" · confidence "+esc(o.confidence||0)+"%":""}</p>${o.next_action?`<p><b>Volgende actie:</b> ${esc(o.next_action)}</p>`:""}</div><div class="clientactions"><button class="queueanalyse small" data-id="${esc(x.id)}" type="button">Analyseer</button><button class="queuetask ghostbtn small" data-id="${esc(x.id)}" type="button">Maak taak</button></div><div id="queue-${esc(x.id)}" class="salesresult"></div></div>`}).join(""):'<p class="muted">Nog geen open saleskansen.</p>'}</div>
</section>
<section class="card">
  <div class="sectionhead"><div><h2>Nieuwe campagne maken</h2><p class="muted">De agent gebruikt actuele CRM-signalen en slaat het resultaat als draft op.</p></div></div>
  <div class="clientformgrid">
    <label>Kanaal<select id="marketingGenerateChannel">${["facebook","instagram","linkedin","email","website","google_business","tiktok"].map(x=>`<option value="${x}">${x.replace("_"," ")}</option>`).join("")}</select></label>
    <label>Doel (optioneel)<input id="marketingGenerateObjective" placeholder="Bijv. meer aanvragen voor dienst X"></label>
  </div>
  <div class="clientactions"><button class="marketingbtn" type="button">Maak campagnedraft</button><button class="marketingweekbtn ghostbtn" type="button">Maak volledig weekplan</button></div>
  <div id="marketingResult" class="marketingresult"></div>
</section>
<section class="card">
  <div class="sectionhead"><div><h2>Recente campagnedrafts</h2><p class="muted">Goedkeuren betekent alleen intern goedkeuren; er wordt niets automatisch gepubliceerd.</p></div></div>
  <div class="flow">${campaigns.length?campaigns.map(c=>`<div class="step campaignrow"><div><b>${esc(c.channel)} · ${esc(c.objective||"Campagne")}</b> <span class="badge">${esc(c.status)}</span><p><strong>${esc(c.hook||"")}</strong></p><p class="muted campaigncontent">${esc(c.content||"")}</p><p class="muted">CTA: ${esc(c.cta||"—")}</p></div><div class="clientactions">${c.status==="draft"?`<button class="campaignstatus small" data-id="${esc(c.id)}" data-status="approved" type="button">Goedkeuren</button>`:""}${c.status!=="archived"?`<button class="campaignstatus ghostbtn small" data-id="${esc(c.id)}" data-status="archived" type="button">Archiveren</button>`:""}</div></div>`).join(""):'<p class="muted">Nog geen campagnedrafts.</p>'}</div>
</section>`;}
if(view==="settings")body=`<section class="pagehead"><span class="eyebrow">ONBOARDING & CONFIGURATIE</span><h1>Bedrijfsinstellingen</h1><p class="muted">Hoe vollediger deze informatie, hoe beter de receptionist antwoordt.</p></section><div class="card formcard"><form id="profile"><label>Bedrijfsnaam</label><input id="pname" maxlength="120" value="${esc(profile.business_name||"")}"><label>Receptionistnaam</label><input id="rname" maxlength="50" value="${esc(profile.receptionist_name||"Ava")}"><label>Beschrijving</label><textarea id="desc">${esc(profile.description||"")}</textarea><label>Diensten — één per regel</label><textarea id="services">${esc(arr(profile.services).join("\n"))}</textarea><label>Openingsuren</label><textarea id="hours">${esc(Object.entries(profile.opening_hours||{}).map(([k,v])=>k+": "+v).join("\n"))}</textarea><label>Kwalificatievragen — één per regel</label><textarea id="questions">${esc(arr(profile.qualification_questions).join("\n"))}</textarea><label>Doorgeven aan medewerker wanneer…</label><textarea id="escalations">${esc(arr(profile.escalation_rules).join("\n"))}</textarea><label>Welkomstbericht widget</label><input id="greeting" maxlength="180" value="${esc(profile.widget_greeting||"Hallo! Waarmee kan ik helpen?")}"><label>Toegestane widget-domeinen — één per regel</label><textarea id="allowedDomains" placeholder="voorbeeld.be\nwww.voorbeeld.be">${esc(arr(profile.widget_allowed_domains).join("\n"))}</textarea><p class="muted">Optioneel. Leeg betekent dat de widget op elk domein kan laden.</p><label>Notificatie e-mail</label><input id="notify" type="email" value="${esc(profile.notification_email||"")}"><label>Voorkeurskanaal opvolging</label><select id="followchannel"><option value="auto" ${profile.preferred_followup_channel==="auto"?"selected":""}>Automatisch</option><option value="email" ${profile.preferred_followup_channel==="email"?"selected":""}>E-mail</option><option value="whatsapp" ${profile.preferred_followup_channel==="whatsapp"?"selected":""}>WhatsApp</option></select><label class="check"><input id="autoenabled" type="checkbox" ${profile.automation_enabled?"checked":""}> Automatische workflow actief</label><div class="privacytools"><button id="exportData" type="button" class="ghostbtn">Exporteer mijn gegevens</button><div id="exportMsg" class="muted"></div></div><label class="check"><input id="wenabled" type="checkbox" ${profile.widget_enabled!==false?"checked":""}> Publieke receptionist actief</label><button>Instellingen opslaan</button></form><div id="pmsg" class="result muted"></div></div>`;
if(view==="integrations"){const emailInt=byChannel("email"),waInt=byChannel("whatsapp"),calInt=byChannel("calendar"),payInt=byChannel("payment"),gOauth=googleOAuthStatus||{};const reason=qs.get("reason")||"";const calendarReason=({state_missing:"Deze callback-URL werd rechtstreeks geopend. Start altijd via de knop ‘Google Agenda koppelen’.",state_invalid:"De beveiligde Google-koppelsessie is verlopen of ongeldig. Start de koppeling opnieuw.",platform_oauth_not_configured:"Google OAuth is nog niet centraal ingesteld. Configureer eerst de Client ID en Client Secret als Platform Owner.",token_exchange_failed:"Google heeft de autorisatiecode niet kunnen omwisselen. Controleer Client ID, Client Secret en redirect URI.",calendar_scope_not_granted:"De vereiste Google Calendar-toegang werd niet toegestaan.",refresh_token_missing:"Google gaf geen refresh token terug. Autoriseer opnieuw en geef toestemming.",callback_failed:"De Google callback is mislukt. Probeer opnieuw."})[reason]||reason||"Onbekende fout";const googlePlatformCard=isPlatformAdmin?`<section class="card formcard platformoauth"><div class="sectionhead"><div><span class="eyebrow">PLATFORM OWNER</span><h2>Google OAuth platforminstellingen</h2><p class="muted">Eenmalige centrale configuratie. Klanten koppelen daarna elk hun eigen Google-account.</p></div><span class="badge">${gOauth.configured?"GECONFIGUREERD":"SETUP NODIG"}</span></div>${googleOAuthLoadError?`<div class="notice">${esc(googleOAuthLoadError)}</div>`:""}<form id="googlePlatformOAuth"><label>Google OAuth Client ID</label><input id="googleClientId" autocomplete="off" placeholder="…apps.googleusercontent.com" value="${esc(gOauth.client_id||"")}"><label>Google OAuth Client Secret</label><input id="googleClientSecret" type="password" autocomplete="new-password" placeholder="${gOauth.has_client_secret?"Leeg laten om bestaande secret te behouden":"GOCSPX-…"}"><label>Authorized redirect URI</label><div class="result copyrow"><code id="googlePlatformRedirect">${esc(gOauth.redirect_uri||"https://ndecxbsrxspkuxjsbndq.supabase.co/functions/v1/google-calendar-oauth-callback")}</code><button class="copybtn" data-copy="googlePlatformRedirect" type="button">Kopieer</button></div><p class="muted">Maak in Google Cloud een OAuth 2.0 Client ID van type <b>Web application</b> en voeg exact deze redirect URI toe onder Authorized redirect URIs. Plak daarna Client ID en Client Secret hierboven.</p><div class="clientactions"><button type="submit">OAuth veilig opslaan</button><a class="ghostbtn" target="_blank" rel="noopener" href="https://console.cloud.google.com/apis/credentials">Open Google Cloud Credentials</a></div></form><div id="googlePlatformOAuthMsg" class="result muted"></div></section>`:"";body=`<section class="pagehead"><span class="eyebrow">PROVIDER ROUTER</span><h1>Integraties</h1><p class="muted">Credentials worden versleuteld server-side opgeslagen en nooit teruggestuurd naar de browser. Alleen actieve tenant-integraties mogen workflowacties uitvoeren.</p></section>${readinessHtml}${googlePlatformCard}<section class="twocol"><div class="card formcard"><h2>E-mail · Resend</h2><p class="muted">Status: <b>${esc(emailInt?.status||"needs_setup")}</b></p><form id="emailIntegration"><label>Afzendernaam</label><input id="resendName" value="${esc(emailInt?.config?.sender_name||profile.business_name||"")}"><label>Afzender e-mail</label><input id="resendEmail" type="email" value="${esc(emailInt?.config?.sender_email||"")}"><label>Reply-to</label><input id="resendReply" type="email" value="${esc(emailInt?.config?.reply_to||"")}"><label>Reviewlink</label><input id="resendReview" type="url" value="${esc(emailInt?.config?.review_url||"")}"><label>Resend API-key</label><input id="resendSecret" type="password" autocomplete="new-password" placeholder="${emailInt?.status==="active"?"Leeg laten om bestaande key te behouden":"re_…"}"><p class="muted">Bij activatie sturen we één technische testmail naar het notificatieadres. Alleen bij API-acceptatie wordt deze koppeling actief.</p><label class="check"><input id="resendActive" type="checkbox" ${emailInt?.status==="active"?"checked":""}> Verifiëren en activeren</label><button>Veilig opslaan</button><button id="disconnectEmail" type="button" class="ghostbtn">Verbinding uitschakelen</button></form><div id="emailIntegrationMsg" class="result muted"></div></div><div class="card formcard"><h2>WhatsApp · Meta Cloud API</h2><p class="muted">Status: <b>${esc(waInt?.status||"needs_setup")}</b></p><form id="waIntegration"><label>Phone Number ID</label><input id="waPhoneId" value="${esc(waInt?.config?.phone_number_id||"")}"><label>Graph API-versie</label><input id="waApiVersion" placeholder="v23.0" value="${esc(waInt?.config?.api_version||"")}"><label>Access token</label><input id="waSecret" type="password" autocomplete="new-password" placeholder="${waInt?.status==="active"?"Leeg laten om bestaande token te behouden":"Permanent access token"}"><label>Template mapping (JSON)</label><textarea id="waTemplates" spellcheck="false">${esc(JSON.stringify(waInt?.config?.templates||{},null,2))}</textarea><label>Reviewlink</label><input id="waReview" type="url" value="${esc(waInt?.config?.review_url||"")}"><label class="check"><input id="waActive" type="checkbox" ${waInt?.status==="active"?"checked":""}> Verbinding verifiëren en activeren</label><button>Veilig opslaan</button><button id="disconnectWa" type="button" class="ghostbtn">Verbinding uitschakelen</button></form><div id="waIntegrationMsg" class="result muted"></div></div></section><section class="twocol"><div class="card formcard"><h2>Agenda · Google Calendar</h2><p class="muted">Status: <b>${esc(calInt?.status||"needs_setup")}</b></p>${qs.get("calendar")==="connected"?'<div class="successbanner"><b>Google Calendar verbonden.</b> Geblokkeerde kalenderjobs worden automatisch hervat.</div>':""}${qs.get("calendar")==="error"?`<div class="notice"><b>Google Calendar kon niet worden gekoppeld.</b> ${esc(calendarReason)}</div>`:""}<p class="muted">Elke organisatie koppelt haar eigen Google-account via OAuth. Refresh tokens worden versleuteld in Vault bewaard.</p><label>OAuth redirect URI</label><div class="result copyrow"><code id="calendarRedirectUri">https://ndecxbsrxspkuxjsbndq.supabase.co/functions/v1/google-calendar-oauth-callback</code><button class="copybtn" data-copy="calendarRedirectUri" type="button">Kopieer</button></div><p class="muted">Scope: Google Calendar events. De runner maakt, wijzigt en verwijdert alleen afspraak-events voor deze tenant.</p><button id="connectCalendar" type="button" ${isPlatformAdmin&&!gOauth.configured?"disabled":""}>${calInt?.status==="active"?"Opnieuw autoriseren":"Google Agenda koppelen"}</button>${isPlatformAdmin&&!gOauth.configured?'<p class="muted">Configureer hierboven eerst Google OAuth. Daarna wordt deze knop actief.</p>':""}<button id="disconnectCalendar" type="button" class="ghostbtn">Verbinding uitschakelen</button><div id="calendarIntegrationMsg" class="result muted"></div></div><div class="card formcard"><h2>Betaling · Stripe Checkout</h2><p class="muted">Status: <b>${esc(payInt?.status||"needs_setup")}</b>${payInt?.config?.stripe_mode?` · modus: <b>${esc(payInt.config.stripe_mode)}</b>`:""}</p><form id="stripeIntegration"><label>Succes-URL</label><input id="stripeSuccess" type="url" placeholder="https://uwsite.be/betaling-gelukt" value="${esc(payInt?.config?.success_url||"")}"><label>Annuleer-URL</label><input id="stripeCancel" type="url" placeholder="https://uwsite.be/betaling-geannuleerd" value="${esc(payInt?.config?.cancel_url||"")}"><label>Omschrijving betaalitem</label><input id="stripeProduct" value="${esc(payInt?.config?.product_name||("Betaling "+(profile.business_name||"")))}"><label>Stripe secret/restricted key</label><input id="stripeSecret" type="password" autocomplete="new-password" placeholder="${payInt?.status==="active"?"Leeg laten om bestaande key te behouden":"sk_… of rk_…"}"><label>Webhook signing secret <span class="muted">(optioneel)</span></label><input id="stripeWebhookSecret" type="password" autocomplete="new-password" placeholder="${payInt?.status==="active"?"Leeg laten om bestaande secret te behouden":"Leeg = automatisch webhook aanmaken"}"><label>Webhook endpoint</label><div class="result copyrow"><code id="paymentWebhookUrl">https://ndecxbsrxspkuxjsbndq.supabase.co/functions/v1/customer-payment-webhook?integration_id=${encodeURIComponent(payInt?.id||"")}</code><button class="copybtn" data-copy="paymentWebhookUrl" type="button">Kopieer</button></div><p class="muted">Met voldoende Stripe-rechten maakt mijn.ai deze webhook automatisch aan en bewaart het signing secret versleuteld. Bij een beperkte key kunt u hem handmatig aanmaken en het whsec_-secret invullen.</p><label class="check"><input id="stripeActive" type="checkbox" ${payInt?.status==="active"?"checked":""}> Stripe-account verifiëren en activeren</label><button>Veilig opslaan</button><button id="disconnectStripe" type="button" class="ghostbtn">Verbinding uitschakelen</button></form><div id="stripeIntegrationMsg" class="result muted"></div></div></section>`;}
if(view==="receptionist")body=`<section class="pagehead"><span class="eyebrow">AI-RECEPTIONIST</span><h1>Testen & publiceren</h1><p class="muted">Test Ava zoals een klant haar ervaart en plaats daarna de widget op uw website.</p></section><section class="twocol"><div class="card"><h2>Live widget</h2><p class="muted">Deelbare URL</p><div class="result copyrow"><b id="widgetUrl">${esc(location.origin+"/?widget="+profile.widget_token)}</b><button class="copybtn" data-copy="widgetUrl">Kopieer</button></div><p class="muted">Zwevende widgetcode — plaats deze één keer op alle pagina’s, bij voorkeur vlak voor &lt;/body&gt;.</p><div class="result copyrow"><code id="embedCode">&lt;script src="${esc(location.origin+"/widget.js")}" data-widget-token="${esc(profile.widget_token)}" defer&gt;&lt;/script&gt;</code><button class="copybtn" data-copy="embedCode">Kopieer</button></div><p class="muted">Dezelfde code werkt in WordPress, Wix, Shopify en gewone HTML. Alleen de widget-token verschilt per bedrijf.</p></div><div class="card chatcard"><h2>${esc(profile.receptionist_name||"Ava")} testen</h2><form id="chat"><div class="chatmeta"><input id="cname" placeholder="Naam prospect"><input id="cemail" placeholder="E-mail (optioneel)" type="email"><input id="cphone" placeholder="Telefoon (optioneel)" type="tel"></div><label class="check consentline"><input id="cconsent" type="checkbox"> Contacttoestemming voor deze testlead.</label><label class="check consentline"><input id="cmarketing" type="checkbox"> Retentietoestemming voor deze testlead.</label><div id="chatlog" class="chatlog"><div class="bubble ai">Hallo, ik ben ${esc(profile.receptionist_name||"Ava")}. Waarmee kan ik helpen?</div></div><div class="chatrow"><input id="cmsg" placeholder="Typ een klantvraag…" required><button class="send">Verstuur</button></div></form><div id="cstatus" class="muted"></div></div></section>`;
