supabase.auth.onAuthStateChange((event,session)=>{if(event==="SIGNED_OUT")authView();if(event==="PASSWORD_RECOVERY"&&!location.search.includes("recovery=1"))location.href="./?recovery=1"});
const qs=new URLSearchParams(location.search);const recovery=qs.get("recovery")==="1";if(recovery){app.innerHTML='<main class="shell"><section class="card formcard"><div class="brand">Reception AI</div><h1>Nieuw wachtwoord</h1><p class="muted">Kies een nieuw wachtwoord van minstens 8 tekens en bevestig het hieronder.</p><form id="recoveryForm"><label>Nieuw wachtwoord</label><input id="newpass" type="password" minlength="8" autocomplete="new-password" required placeholder="Minstens 8 tekens"><label>Bevestig wachtwoord</label><input id="newpass2" type="password" minlength="8" autocomplete="new-password" required placeholder="Herhaal uw wachtwoord"><button>Wachtwoord opslaan</button></form><div id="recoveryMsg" class="result muted"></div></section></main>';document.querySelector("#recoveryForm").onsubmit=async e=>{e.preventDefault();const m=document.querySelector("#recoveryMsg"),p1=document.querySelector("#newpass").value,p2=document.querySelector("#newpass2").value,btn=e.currentTarget.querySelector("button");if(p1.length<8){m.textContent="Gebruik minstens 8 tekens.";return}if(p1!==p2){m.textContent="De twee wachtwoorden komen niet overeen.";return}btn.disabled=true;m.textContent="Wachtwoord wordt gewijzigd…";const {error}=await supabase.auth.updateUser({password:p1});btn.disabled=false;if(error)m.textContent="Wijzigen mislukt: "+error.message;else{m.textContent="✓ Wachtwoord gewijzigd. U wordt doorgestuurd naar inloggen…";await supabase.auth.signOut();setTimeout(()=>location.href="./?auth=1&reset=success",900)}}}const widget=qs.get("widget");if(!recovery&&widget)publicWidgetView(widget);else if(!recovery){const page=qs.get("page");if(page==="privacy"||page==="terms")legalView(page);else{const {data:{session}}=await supabase.auth.getSession();session?dashboard():authView();}}